CREATE TABLE "ImageMap" ("id" TEXT NOT NULL PRIMARY KEY, "ownerId" TEXT, "data" JSONB NOT NULL, "image" BYTEA NOT NULL, "thumbnail" BYTEA NOT NULL, "width" INTEGER NOT NULL, "height" INTEGER NOT NULL, "size" INTEGER NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "archived" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL); CREATE INDEX "ImageMap_ownerId_archived_idx" ON "ImageMap"("ownerId", "archived");
